#include <vector>
#include <cstddef>
#include <omp.h>

void luFactorize(std::vector<double> &A, size_t N) {
    if (N == 0) return;
    if (A.size() < N * N) return; // or throw; kept non-throwing/self-contained

    auto idx = [N](size_t i, size_t j) -> size_t { return i * N + j; };

    for (size_t k = 0; k < N; ++k) {
        const double pivot = A[idx(k, k)];
        // No pivoting; assume pivot != 0.

        // Compute multipliers (L column k below diagonal): A[i,k] /= pivot
        #pragma omp parallel for default(none) shared(A, N, k) firstprivate(pivot, idx)
        for (std::ptrdiff_t ii = static_cast<std::ptrdiff_t>(k) + 1;
             ii < static_cast<std::ptrdiff_t>(N); ++ii) {
            const size_t i = static_cast<size_t>(ii);
            A[idx(i, k)] /= pivot;
        }

        // Update trailing submatrix: A[i,j] -= A[i,k] * A[k,j]
        #pragma omp parallel for default(none) shared(A, N, k) firstprivate(idx) collapse(2)
        for (std::ptrdiff_t ii = static_cast<std::ptrdiff_t>(k) + 1;
             ii < static_cast<std::ptrdiff_t>(N); ++ii) {
            for (std::ptrdiff_t jj = static_cast<std::ptrdiff_t>(k) + 1;
                 jj < static_cast<std::ptrdiff_t>(N); ++jj) {
                const size_t i = static_cast<size_t>(ii);
                const size_t j = static_cast<size_t>(jj);
                A[idx(i, j)] -= A[idx(i, k)] * A[idx(k, j)];
            }
        }
    }
}
